import React, { createContext, useState, useContext, useEffect } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [token, setToken] = useState(null);

  // Проверяем наличие сохранённой сессии при загрузке
  useEffect(() => {
    const initAuth = async () => {
      try {
        // Проверяем localStorage на наличие токена
        const storedToken = localStorage.getItem('auth_token');
        const storedUser = localStorage.getItem('auth_user');

        if (storedToken && storedUser) {
          // Проверяем валидность токена
          const isValid = await validateToken(storedToken);

          if (isValid) {
            setToken(storedToken);
            setUser(JSON.parse(storedUser));
          } else {
            // Если токен невалиден, очищаем localStorage
            clearStorage();
          }
        }
      } catch (error) {
        console.error('Auth initialization error:', error);
        clearStorage();
      } finally {
        setLoading(false);
      }
    };

    initAuth();
  }, []);

  // Функция валидации токена
  const validateToken = async (token) => {
    try {
      // Здесь можно добавить проверку токена на сервере
      // или проверить его срок действия
      const response = await fetch('/api/auth/validate', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });

      if (response.ok) {
        return true;
      }
      return false;
    } catch (error) {
      console.error('Token validation error:', error);
      return false;
    }
  };

  // Регистрация
  const register = async (username, email, password) => {
    try {
      setLoading(true);

      // Отправляем данные на сервер
      const response = await fetch('/api/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          username,
          email,
          password,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Registration failed');
      }

      // Сохраняем токен и данные пользователя
      const { token: authToken, user: userData } = data;

      // Сохраняем в состоянии
      setUser(userData);
      setToken(authToken);

      // Сохраняем в localStorage для запоминания
      localStorage.setItem('auth_token', authToken);
      localStorage.setItem('auth_user', JSON.stringify(userData));

      // Устанавливаем токен в заголовки по умолчанию для будущих запросов
      setAuthHeader(authToken);

      return { success: true, user: userData };

    } catch (error) {
      console.error('Registration error:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // Вход
  const login = async (email, password) => {
    try {
      setLoading(true);

      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          email,
          password,
          rememberMe: true, // Флаг для долгосрочной сессии
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Login failed');
      }

      // Сохраняем токен и данные пользователя
      const { token: authToken, user: userData } = data;

      // Сохраняем в состоянии
      setUser(userData);
      setToken(authToken);

      // Сохраняем в localStorage
      localStorage.setItem('auth_token', authToken);
      localStorage.setItem('auth_user', JSON.stringify(userData));

      // Устанавливаем токен в заголовки
      setAuthHeader(authToken);

      return { success: true, user: userData };

    } catch (error) {
      console.error('Login error:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // Выход
  const logout = async () => {
    try {
      // Опционально: отправляем запрос на сервер для инвалидации токена
      if (token) {
        await fetch('/api/auth/logout', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        });
      }
    } catch (error) {
      console.error('Logout error:', error);
    } finally {
      // Очищаем состояние
      setUser(null);
      setToken(null);

      // Очищаем localStorage
      clearStorage();

      // Убираем заголовок авторизации
      deleteAuthHeader();
    }
  };

  // Обновление данных пользователя
  const updateUser = (updatedData) => {
    setUser(prev => {
      const newUser = { ...prev, ...updatedData };
      // Обновляем в localStorage
      localStorage.setItem('auth_user', JSON.stringify(newUser));
      return newUser;
    });
  };

  // Вспомогательные функции
  const setAuthHeader = (token) => {
    // Устанавливаем заголовок авторизации для всех последующих запросов
    // Это можно сделать через axios.defaults или перехватчики запросов
    if (typeof window !== 'undefined') {
      // Для fetch можно использовать перехватчик
      window.authToken = token;
    }
  };

  const deleteAuthHeader = () => {
    if (typeof window !== 'undefined') {
      delete window.authToken;
    }
  };

  const clearStorage = () => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('auth_user');
    sessionStorage.removeItem('auth_token'); // Очищаем и sessionStorage на всякий случай
    sessionStorage.removeItem('auth_user');
  };

  // Проверяем, авторизован ли пользователь
  const isAuthenticated = !!user && !!token;

  const value = {
    user,
    token,
    loading,
    isAuthenticated,
    register,
    login,
    logout,
    updateUser,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
